library(tidyverse)


attacks &lt;- read_rds("data/attacks.rds")


attacks |&gt;
  filter(!is.na(Activity), Fatal_clean != "Unknown") |&gt;
  count(Activity, Fatal_clean, name = "attacks") |&gt;
  group_by(Activity) |&gt;
  filter(sum(attacks) &gt;= 50) |&gt;
  ungroup() |&gt;
  ggplot(aes(
    x = fct_reorder(Activity, attacks, .fun = sum),
    y = attacks,
    fill = Fatal_clean
  )) +
  geom_col(position = "dodge") +
  coord_flip() +
  labs(
    x = "Activity",
    y = "Number of attacks",
    fill = "Outcome"
  ) +
  theme_minimal()
